/**
 * Helper to sanitize Storybook date control args.
 * Storybook date controls can pass dates as Date objects, timestamps, or strings.
 * This normalizes them and filters out invalid/incomplete dates.
 * Returns undefined if the date is invalid so the component can use its own defaults.
 */
export declare const getSafeDate: (date: Date | string | number | null | undefined) => Date | undefined;
/**
 * Get the default minimum date for Storybook stories (1 year before the reference date).
 * Centralizes the default minDate calculation to ensure consistency across all stories.
 *
 * @param referenceDate - The date to calculate from. Defaults to today.
 * @returns Date object 1 year in the past
 */
export declare const getDefaultMinDate: (referenceDate?: Date) => Date;
/**
 * Get the default maximum date for Storybook stories (3 months after the reference date).
 * Centralizes the default maxDate calculation to ensure consistency across all stories.
 *
 * @param referenceDate - The date to calculate from. Defaults to today.
 * @returns Date object 3 months in the future
 */
export declare const getDefaultMaxDate: (referenceDate?: Date) => Date;
